export default async function install(app){const reactiveUtils=await app.import('esri/core/reactiveUtils');const originals=new Map();const apply=popup=>{if(!popup?.dockOptions)return;if(!originals.has(popup))originals.set(popup,popup.dockOptions.buttonEnabled);popup.dockOptions={...popup.dockOptions,buttonEnabled:false};};const handle=reactiveUtils.watch(()=>app.view.popup,popup=>apply(popup),{initial:true});app.onCleanup(()=>{handle.remove();for(const [popup,buttonEnabled] of originals){if(!popup.destroyed)popup.dockOptions={...popup.dockOptions,buttonEnabled};}});return {dockButtonEnabled:app.view.popup?.dockOptions?.buttonEnabled};}